window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-3b3943d88a27ce49"]={"versions": [{"id": "FIG-3b3943d88a27ce49", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (AUTOSAR Meta-Modell-Ausschnitt, Structural Pattern).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Timing Extensions (<code>TPS_TimingExtensions</code>, R4.3.1), Kapitel Event- und Timing-Modellierung.\n</li><li><strong>Technischer Zweck:</strong> Eindeutige Adressierung und Instanziierung von Variablen-Datenstrukturen (<code>VariableDataPrototype</code> bzw. Unterelemente von Composite-Datentypen) über SW-C-Hierarchieebenen hinweg. Durch das <code>AtpInstanceRef</code>-Muster wird eineindeutig vom System-/Kompositionstyp über geschachtelte Komponenten- und Port-Prototypen bis zum spezifischen Datenelement navigiert, um Timing-Events, Constraints oder Beobachtungspunkte präzise an ein Laufzeit-Datum zu binden.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metaklassen und Stereotypen</h5>\n<ul class=\"fig-list\"><li><strong><code>AutosarVariableInstance</code></strong> (<code>«Identifiable»</code>): Repräsentiert die konkrete, benannte Instanz einer Variable im Systemkontext für Timing-Analysen. Enthält via 1:1-Komposition (<code>+variableInstance 1</code>) die Instanzreferenz.\n</li><li><strong><code>InstanceRefs::VariableInComponentInstanceRef</code></strong> (<code>«AtpInstanceRef»</code>): Kernklasse zur Realisierung des standardisierten AUTOSAR-InstanceRef-Mechanismus für Variablen.\n</li><li><strong><code>Components::SwComponentType</code></strong> (<code>«ARElement»</code>, <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code>, <code>«AtpType»</code>): Wurzel der Dekomposition (z. B. Composition-Type).\n</li><li><strong><code>Composition::SwComponentPrototype</code></strong> (<code>«AtpPrototype»</code>): Repräsentiert die Verwendung eines Komponenten-Typs innerhalb einer Komposition.\n</li><li><strong><code>Components::PortPrototype</code></strong> (<code>«AtpBlueprintable»</code>, <code>«AtpPrototype»</code>): Kommunikations-Port (Sender/Receiver- oder NvData-Port) am Komponenten-Prototyp.\n</li><li><strong><code>DataPrototypes::DataPrototype</code></strong> (<code>«AtpPrototype»</code>): Abstrakte Basisklasse aller Datenprototypen.\n<ul class=\"fig-list\"><li><strong><code>DataPrototypes::AutosarDataPrototype</code></strong>: Spezialisierung für AUTOSAR-Datenelemente.\n<ul class=\"fig-list\"><li><strong><code>DataPrototypes::VariableDataPrototype</code></strong>: Konkretes atomares oder zusammengesetztes Variablenelement an einem Port.\n</li></ul>\n</li><li><strong><code>DataPrototypes::ApplicationCompositeElementDataPrototype</code></strong>: Sub-Element innerhalb eines strukturierten Datentyps (Record-/Array-Element).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Assoziationen, Kardinalitäten &amp; Semantik</h5>\n<ul class=\"fig-list\"><li><strong><code>+base: SwComponentType</code> [1]</strong> (<code>«atpDerived»</code>, <code>{redefines atpBase}</code>): Definiert den Wurzenkontext der Instanziierung.\n</li><li>**<code>+contextComponent: SwComponentPrototype</code> [0..\\*]** (<code>{ordered, subsets atpContextElement}</code>): Geordnete Pfadliste geschachtelter Subkomponenten von der Wurzel bis zur Zielkomponente.\n</li><li><strong><code>SwComponentPrototype</code> → <code>SwComponentType</code>:</strong> <code>+type 1 {redefines atpType}</code> mit Stereotyp <code>«isOfType»</code>.\n</li><li><strong><code>+contextPortPrototype: PortPrototype</code> [1]</strong> (<code>{subsets atpContextElement}</code>): Eindeutiger Port an der adressierten Blatt-Komponente.\n</li><li><strong><code>+rootVariableDataPrototype: VariableDataPrototype</code> [0..1]</strong> (<code>{subsets atpContextElement}</code>): Wurzelelement der Schnittstelle bei Zugriff auf zusammengesetzte Strukturen.\n</li><li>**<code>+contextDataPrototype: ApplicationCompositeElementDataPrototype</code> [0..\\*]** (<code>{ordered, subsets atpContextElement}</code>): Geordnete Kette von Composite-Elementen zur Indizierung in geschachtelte Records/Arrays.\n</li><li><strong><code>+targetDataProtoype: DataPrototype</code> [1]</strong> (<code>{redefines atpTarget}</code>): Das endgültig referenzierte Ziel-Datenelement (Blattknoten der Referenz).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Nicht zutreffend (rein statisches Metamodell):</strong> Das Diagramm definiert kein Laufzeitverhalten, sondern das deklarative XML-/ARXML-Schema zur Referenzauflösung.\n</li><li><strong>Pfadauflösungs-Sequenz (Modell-Parser / Tooling):</strong>\n<ol class=\"fig-list\"><li>Identifikation des Root-Containers (<code>base: SwComponentType</code>).\n</li><li>Iterative Traversierung des geordneten Arrays <code>contextComponent</code> zur Lokalisierung der Zielkomponente in der Instanzhierarchie.\n</li><li>Auflösung des Schnittstellen-Ports über <code>contextPortPrototype</code>.\n</li><li>Bestimmung des Wurzel-Datenelements via <code>rootVariableDataPrototype</code> (falls Composite) oder direkter Verweis auf das Ziel via <code>targetDataProtoype</code>.\n</li><li>Sukzessive Dereferenzierung entlang <code>contextDataPrototype</code> zur Bestimmung des spezifischen Feldes bei Composite-Typen.\n</li></ol>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ARXML-Serialisierung &amp; Toolchain:</strong>\n<ul class=\"fig-list\"><li>Werkzeuge (z. B. DaVinci, EB tresos, Timing Architects) nutzen diese Struktur zur Erzeugung des XML-Tags <code>&lt;VARIABLE-IN-COMPONENT-INSTANCE-REF&gt;</code>.\n</li><li>Das Weglassen von Zwischenknoten in <code>contextComponent</code> oder <code>contextDataPrototype</code> führt zu Schema-Validierungsfehlern (<code>SUBSET_CONTEXT</code>-Verletzung).\n</li></ul>\n</li><li><strong>BSW- / RTE-Konsequenzen:</strong>\n<ul class=\"fig-list\"><li>Für RTE- und MCAL-Entwickler bestimmt dieser Pfad, welche RTE-Puffer, Shared-Memory-Bereiche oder Task-lokale Symbole (<code>Rte_Read_&lt;p&gt;_&lt;o&gt;</code>, <code>Rte_Write_&lt;p&gt;_&lt;o&gt;</code>) mit Timing-Events überwacht werden.\n</li></ul>\n</li><li><strong>Flache vs. hierarchische Ports:</strong>\n<ul class=\"fig-list\"><li>Ist die Variable direkt ein atomares <code>VariableDataPrototype</code> am Port, entfallen <code>rootVariableDataPrototype</code> und <code>contextDataPrototype</code>; <code>targetDataProtoype</code> referenziert direkt das <code>VariableDataPrototype</code>.\n</li></ul>\n</li><li><strong>Ordering-Vorschrift:</strong>\n<ul class=\"fig-list\"><li><code>{ordered}</code> bei <code>contextComponent</code> und <code>contextDataPrototype</code> erzwingt eine strikte Top-Down-Reihenfolge in der ARXML-Datei; Vertauschungen korrumpieren die Referenz.\n</li></ul>\n</li></ul>"}, {"id": "FIG-2b7f44590b45d4d7", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (AUTOSAR Meta-Modell-Ausschnitt, Structural Pattern).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Timing Extensions (<code>TPS_TimingExtensions</code>, R4.3.1), Kapitel Event- und Timing-Modellierung.\n</li><li><strong>Technischer Zweck:</strong> Eindeutige Adressierung und Instanziierung von Variablen-Datenstrukturen (<code>VariableDataPrototype</code> bzw. Unterelemente von Composite-Datentypen) über SW-C-Hierarchieebenen hinweg. Durch das <code>AtpInstanceRef</code>-Muster wird eineindeutig vom System-/Kompositionstyp über geschachtelte Komponenten- und Port-Prototypen bis zum spezifischen Datenelement navigiert, um Timing-Events, Constraints oder Beobachtungspunkte präzise an ein Laufzeit-Datum zu binden.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metaklassen und Stereotypen</h5>\n<ul class=\"fig-list\"><li><strong><code>AutosarVariableInstance</code></strong> (<code>«Identifiable»</code>): Repräsentiert die konkrete, benannte Instanz einer Variable im Systemkontext für Timing-Analysen. Enthält via 1:1-Komposition (<code>+variableInstance 1</code>) die Instanzreferenz.\n</li><li><strong><code>InstanceRefs::VariableInComponentInstanceRef</code></strong> (<code>«AtpInstanceRef»</code>): Kernklasse zur Realisierung des standardisierten AUTOSAR-InstanceRef-Mechanismus für Variablen.\n</li><li><strong><code>Components::SwComponentType</code></strong> (<code>«ARElement»</code>, <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code>, <code>«AtpType»</code>): Wurzel der Dekomposition (z. B. Composition-Type).\n</li><li><strong><code>Composition::SwComponentPrototype</code></strong> (<code>«AtpPrototype»</code>): Repräsentiert die Verwendung eines Komponenten-Typs innerhalb einer Komposition.\n</li><li><strong><code>Components::PortPrototype</code></strong> (<code>«AtpBlueprintable»</code>, <code>«AtpPrototype»</code>): Kommunikations-Port (Sender/Receiver- oder NvData-Port) am Komponenten-Prototyp.\n</li><li><strong><code>DataPrototypes::DataPrototype</code></strong> (<code>«AtpPrototype»</code>): Abstrakte Basisklasse aller Datenprototypen.\n<ul class=\"fig-list\"><li><strong><code>DataPrototypes::AutosarDataPrototype</code></strong>: Spezialisierung für AUTOSAR-Datenelemente.\n<ul class=\"fig-list\"><li><strong><code>DataPrototypes::VariableDataPrototype</code></strong>: Konkretes atomares oder zusammengesetztes Variablenelement an einem Port.\n</li></ul>\n</li><li><strong><code>DataPrototypes::ApplicationCompositeElementDataPrototype</code></strong>: Sub-Element innerhalb eines strukturierten Datentyps (Record-/Array-Element).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Assoziationen, Kardinalitäten &amp; Semantik</h5>\n<ul class=\"fig-list\"><li><strong><code>+base: SwComponentType</code> [1]</strong> (<code>«atpDerived»</code>, <code>{redefines atpBase}</code>): Definiert den Wurzenkontext der Instanziierung.\n</li><li>**<code>+contextComponent: SwComponentPrototype</code> [0..\\*]** (<code>{ordered, subsets atpContextElement}</code>): Geordnete Pfadliste geschachtelter Subkomponenten von der Wurzel bis zur Zielkomponente.\n</li><li><strong><code>SwComponentPrototype</code> → <code>SwComponentType</code>:</strong> <code>+type 1 {redefines atpType}</code> mit Stereotyp <code>«isOfType»</code>.\n</li><li><strong><code>+contextPortPrototype: PortPrototype</code> [1]</strong> (<code>{subsets atpContextElement}</code>): Eindeutiger Port an der adressierten Blatt-Komponente.\n</li><li><strong><code>+rootVariableDataPrototype: VariableDataPrototype</code> [0..1]</strong> (<code>{subsets atpContextElement}</code>): Wurzelelement der Schnittstelle bei Zugriff auf zusammengesetzte Strukturen.\n</li><li>**<code>+contextDataPrototype: ApplicationCompositeElementDataPrototype</code> [0..\\*]** (<code>{ordered, subsets atpContextElement}</code>): Geordnete Kette von Composite-Elementen zur Indizierung in geschachtelte Records/Arrays.\n</li><li><strong><code>+targetDataProtoype: DataPrototype</code> [1]</strong> (<code>{redefines atpTarget}</code>): Das endgültig referenzierte Ziel-Datenelement (Blattknoten der Referenz).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Nicht zutreffend (rein statisches Metamodell):</strong> Das Diagramm definiert kein Laufzeitverhalten, sondern das deklarative XML-/ARXML-Schema zur Referenzauflösung.\n</li><li><strong>Pfadauflösungs-Sequenz (Modell-Parser / Tooling):</strong>\n<ol class=\"fig-list\"><li>Identifikation des Root-Containers (<code>base: SwComponentType</code>).\n</li><li>Iterative Traversierung des geordneten Arrays <code>contextComponent</code> zur Lokalisierung der Zielkomponente in der Instanzhierarchie.\n</li><li>Auflösung des Schnittstellen-Ports über <code>contextPortPrototype</code>.\n</li><li>Bestimmung des Wurzel-Datenelements via <code>rootVariableDataPrototype</code> (falls Composite) oder direkter Verweis auf das Ziel via <code>targetDataProtoype</code>.\n</li><li>Sukzessive Dereferenzierung entlang <code>contextDataPrototype</code> zur Bestimmung des spezifischen Feldes bei Composite-Typen.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ARXML-Serialisierung &amp; Toolchain:</strong>\n<ul class=\"fig-list\"><li>Werkzeuge (z. B. DaVinci, EB tresos, Timing Architects) nutzen diese Struktur zur Erzeugung des XML-Tags <code>&lt;VARIABLE-IN-COMPONENT-INSTANCE-REF&gt;</code>.\n</li><li>Das Weglassen von Zwischenknoten in <code>contextComponent</code> oder <code>contextDataPrototype</code> führt zu Schema-Validierungsfehlern (<code>SUBSET_CONTEXT</code>-Verletzung).\n</li></ul>\n</li><li><strong>BSW- / RTE-Konsequenzen:</strong>\n<ul class=\"fig-list\"><li>Für RTE- und MCAL-Entwickler bestimmt dieser Pfad, welche RTE-Puffer, Shared-Memory-Bereiche oder Task-lokale Symbole (<code>Rte_Read_&lt;p&gt;_&lt;o&gt;</code>, <code>Rte_Write_&lt;p&gt;_&lt;o&gt;</code>) mit Timing-Events überwacht werden.\n</li></ul>\n</li><li><strong>Flache vs. hierarchische Ports:</strong>\n<ul class=\"fig-list\"><li>Ist die Variable direkt ein atomares <code>VariableDataPrototype</code> am Port, entfallen <code>rootVariableDataPrototype</code> und <code>contextDataPrototype</code>; <code>targetDataProtoype</code> referenziert direkt das <code>VariableDataPrototype</code>.\n</li></ul>\n</li><li><strong>Ordering-Vorschrift:</strong>\n<ul class=\"fig-list\"><li><code>{ordered}</code> bei <code>contextComponent</code> und <code>contextDataPrototype</code> erzwingt eine strikte Top-Down-Reihenfolge in der ARXML-Datei; Vertauschungen korrumpieren die Referenz.\n</li></ul>\n</li></ul>"}, {"id": "FIG-93df5ad9225607cb", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (AUTOSAR Meta-Modell-Ausschnitt, Structural Pattern).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Timing Extensions (<code>TPS_TimingExtensions</code>, R4.3.1), Kapitel Event- und Timing-Modellierung.\n</li><li><strong>Technischer Zweck:</strong> Eindeutige Adressierung und Instanziierung von Variablen-Datenstrukturen (<code>VariableDataPrototype</code> bzw. Unterelemente von Composite-Datentypen) über SW-C-Hierarchieebenen hinweg. Durch das <code>AtpInstanceRef</code>-Muster wird eineindeutig vom System-/Kompositionstyp über geschachtelte Komponenten- und Port-Prototypen bis zum spezifischen Datenelement navigiert, um Timing-Events, Constraints oder Beobachtungspunkte präzise an ein Laufzeit-Datum zu binden.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metaklassen und Stereotypen</h5>\n<ul class=\"fig-list\"><li><strong><code>AutosarVariableInstance</code></strong> (<code>«Identifiable»</code>): Repräsentiert die konkrete, benannte Instanz einer Variable im Systemkontext für Timing-Analysen. Enthält via 1:1-Komposition (<code>+variableInstance 1</code>) die Instanzreferenz.\n</li><li><strong><code>InstanceRefs::VariableInComponentInstanceRef</code></strong> (<code>«AtpInstanceRef»</code>): Kernklasse zur Realisierung des standardisierten AUTOSAR-InstanceRef-Mechanismus für Variablen.\n</li><li><strong><code>Components::SwComponentType</code></strong> (<code>«ARElement»</code>, <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code>, <code>«AtpType»</code>): Wurzel der Dekomposition (z. B. Composition-Type).\n</li><li><strong><code>Composition::SwComponentPrototype</code></strong> (<code>«AtpPrototype»</code>): Repräsentiert die Verwendung eines Komponenten-Typs innerhalb einer Komposition.\n</li><li><strong><code>Components::PortPrototype</code></strong> (<code>«AtpBlueprintable»</code>, <code>«AtpPrototype»</code>): Kommunikations-Port (Sender/Receiver- oder NvData-Port) am Komponenten-Prototyp.\n</li><li><strong><code>DataPrototypes::DataPrototype</code></strong> (<code>«AtpPrototype»</code>): Abstrakte Basisklasse aller Datenprototypen.\n<ul class=\"fig-list\"><li><strong><code>DataPrototypes::AutosarDataPrototype</code></strong>: Spezialisierung für AUTOSAR-Datenelemente.\n<ul class=\"fig-list\"><li><strong><code>DataPrototypes::VariableDataPrototype</code></strong>: Konkretes atomares oder zusammengesetztes Variablenelement an einem Port.\n</li></ul>\n</li><li><strong><code>DataPrototypes::ApplicationCompositeElementDataPrototype</code></strong>: Sub-Element innerhalb eines strukturierten Datentyps (Record-/Array-Element).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Assoziationen, Kardinalitäten &amp; Semantik</h5>\n<ul class=\"fig-list\"><li><strong><code>+base: SwComponentType</code> [1]</strong> (<code>«atpDerived»</code>, <code>{redefines atpBase}</code>): Definiert den Wurzenkontext der Instanziierung.\n</li><li>**<code>+contextComponent: SwComponentPrototype</code> [0..\\*]** (<code>{ordered, subsets atpContextElement}</code>): Geordnete Pfadliste geschachtelter Subkomponenten von der Wurzel bis zur Zielkomponente.\n</li><li><strong><code>SwComponentPrototype</code> → <code>SwComponentType</code>:</strong> <code>+type 1 {redefines atpType}</code> mit Stereotyp <code>«isOfType»</code>.\n</li><li><strong><code>+contextPortPrototype: PortPrototype</code> [1]</strong> (<code>{subsets atpContextElement}</code>): Eindeutiger Port an der adressierten Blatt-Komponente.\n</li><li><strong><code>+rootVariableDataPrototype: VariableDataPrototype</code> [0..1]</strong> (<code>{subsets atpContextElement}</code>): Wurzelelement der Schnittstelle bei Zugriff auf zusammengesetzte Strukturen.\n</li><li>**<code>+contextDataPrototype: ApplicationCompositeElementDataPrototype</code> [0..\\*]** (<code>{ordered, subsets atpContextElement}</code>): Geordnete Kette von Composite-Elementen zur Indizierung in geschachtelte Records/Arrays.\n</li><li><strong><code>+targetDataProtoype: DataPrototype</code> [1]</strong> (<code>{redefines atpTarget}</code>): Das endgültig referenzierte Ziel-Datenelement (Blattknoten der Referenz).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Nicht zutreffend (rein statisches Metamodell):</strong> Das Diagramm definiert kein Laufzeitverhalten, sondern das deklarative XML-/ARXML-Schema zur Referenzauflösung.\n</li><li><strong>Pfadauflösungs-Sequenz (Modell-Parser / Tooling):</strong>\n<ol class=\"fig-list\"><li>Identifikation des Root-Containers (<code>base: SwComponentType</code>).\n</li><li>Iterative Traversierung des geordneten Arrays <code>contextComponent</code> zur Lokalisierung der Zielkomponente in der Instanzhierarchie.\n</li><li>Auflösung des Schnittstellen-Ports über <code>contextPortPrototype</code>.\n</li><li>Bestimmung des Wurzel-Datenelements via <code>rootVariableDataPrototype</code> (falls Composite) oder direkter Verweis auf das Ziel via <code>targetDataProtoype</code>.\n</li><li>Sukzessive Dereferenzierung entlang <code>contextDataPrototype</code> zur Bestimmung des spezifischen Feldes bei Composite-Typen.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ARXML-Serialisierung &amp; Toolchain:</strong>\n<ul class=\"fig-list\"><li>Werkzeuge (z. B. DaVinci, EB tresos, Timing Architects) nutzen diese Struktur zur Erzeugung des XML-Tags <code>&lt;VARIABLE-IN-COMPONENT-INSTANCE-REF&gt;</code>.\n</li><li>Das Weglassen von Zwischenknoten in <code>contextComponent</code> oder <code>contextDataPrototype</code> führt zu Schema-Validierungsfehlern (<code>SUBSET_CONTEXT</code>-Verletzung).\n</li></ul>\n</li><li><strong>BSW- / RTE-Konsequenzen:</strong>\n<ul class=\"fig-list\"><li>Für RTE- und MCAL-Entwickler bestimmt dieser Pfad, welche RTE-Puffer, Shared-Memory-Bereiche oder Task-lokale Symbole (<code>Rte_Read_&lt;p&gt;_&lt;o&gt;</code>, <code>Rte_Write_&lt;p&gt;_&lt;o&gt;</code>) mit Timing-Events überwacht werden.\n</li></ul>\n</li><li><strong>Flache vs. hierarchische Ports:</strong>\n<ul class=\"fig-list\"><li>Ist die Variable direkt ein atomares <code>VariableDataPrototype</code> am Port, entfallen <code>rootVariableDataPrototype</code> und <code>contextDataPrototype</code>; <code>targetDataProtoype</code> referenziert direkt das <code>VariableDataPrototype</code>.\n</li></ul>\n</li><li><strong>Ordering-Vorschrift:</strong>\n<ul class=\"fig-list\"><li><code>{ordered}</code> bei <code>contextComponent</code> und <code>contextDataPrototype</code> erzwingt eine strikte Top-Down-Reihenfolge in der ARXML-Datei; Vertauschungen korrumpieren die Referenz.\n</li></ul>\n</li></ul>"}, {"id": "FIG-5f68178a3c5ee387", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (AUTOSAR Meta-Modell-Ausschnitt, Structural Pattern).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Timing Extensions (<code>TPS_TimingExtensions</code>, R4.3.1), Kapitel Event- und Timing-Modellierung.\n</li><li><strong>Technischer Zweck:</strong> Eindeutige Adressierung und Instanziierung von Variablen-Datenstrukturen (<code>VariableDataPrototype</code> bzw. Unterelemente von Composite-Datentypen) über SW-C-Hierarchieebenen hinweg. Durch das <code>AtpInstanceRef</code>-Muster wird eineindeutig vom System-/Kompositionstyp über geschachtelte Komponenten- und Port-Prototypen bis zum spezifischen Datenelement navigiert, um Timing-Events, Constraints oder Beobachtungspunkte präzise an ein Laufzeit-Datum zu binden.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metaklassen und Stereotypen</h5>\n<ul class=\"fig-list\"><li><strong><code>AutosarVariableInstance</code></strong> (<code>«Identifiable»</code>): Repräsentiert die konkrete, benannte Instanz einer Variable im Systemkontext für Timing-Analysen. Enthält via 1:1-Komposition (<code>+variableInstance 1</code>) die Instanzreferenz.\n</li><li><strong><code>InstanceRefs::VariableInComponentInstanceRef</code></strong> (<code>«AtpInstanceRef»</code>): Kernklasse zur Realisierung des standardisierten AUTOSAR-InstanceRef-Mechanismus für Variablen.\n</li><li><strong><code>Components::SwComponentType</code></strong> (<code>«ARElement»</code>, <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code>, <code>«AtpType»</code>): Wurzel der Dekomposition (z. B. Composition-Type).\n</li><li><strong><code>Composition::SwComponentPrototype</code></strong> (<code>«AtpPrototype»</code>): Repräsentiert die Verwendung eines Komponenten-Typs innerhalb einer Komposition.\n</li><li><strong><code>Components::PortPrototype</code></strong> (<code>«AtpBlueprintable»</code>, <code>«AtpPrototype»</code>): Kommunikations-Port (Sender/Receiver- oder NvData-Port) am Komponenten-Prototyp.\n</li><li><strong><code>DataPrototypes::DataPrototype</code></strong> (<code>«AtpPrototype»</code>): Abstrakte Basisklasse aller Datenprototypen.\n<ul class=\"fig-list\"><li><strong><code>DataPrototypes::AutosarDataPrototype</code></strong>: Spezialisierung für AUTOSAR-Datenelemente.\n<ul class=\"fig-list\"><li><strong><code>DataPrototypes::VariableDataPrototype</code></strong>: Konkretes atomares oder zusammengesetztes Variablenelement an einem Port.\n</li></ul>\n</li><li><strong><code>DataPrototypes::ApplicationCompositeElementDataPrototype</code></strong>: Sub-Element innerhalb eines strukturierten Datentyps (Record-/Array-Element).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Assoziationen, Kardinalitäten &amp; Semantik</h5>\n<ul class=\"fig-list\"><li><strong><code>+base: SwComponentType</code> [1]</strong> (<code>«atpDerived»</code>, <code>{redefines atpBase}</code>): Definiert den Wurzelkontext der Instanziierung.\n</li><li>**<code>+contextComponent: SwComponentPrototype</code> [0..*]** (<code>{ordered, subsets atpContextElement}</code>): Geordnete Pfadliste geschachtelter Subkomponenten von der Wurzel bis zur Zielkomponente.\n</li><li><strong><code>SwComponentPrototype</code> → <code>SwComponentType</code>:</strong> <code>+type 0..1 {redefines atpType}</code> mit Stereotyp <code>«isOfType»</code>.\n</li><li><strong><code>+contextPortPrototype: PortPrototype</code> [1]</strong> (<code>{subsets atpContextElement}</code>): Eindeutiger Port an der adressierten Blatt-Komponente.\n</li><li><strong><code>+rootVariableDataPrototype: VariableDataPrototype</code> [0..1]</strong> (<code>{subsets atpContextElement}</code>): Wurzelelement der Schnittstelle bei Zugriff auf zusammengesetzte Strukturen.\n</li><li>**<code>+contextDataPrototype: ApplicationCompositeElementDataPrototype</code> [0..*]** (<code>{ordered, subsets atpContextElement}</code>): Geordnete Kette von Composite-Elementen zur Indizierung in geschachtelte Records/Arrays.\n</li><li><strong><code>+targetDataProtoype: DataPrototype</code> [1]</strong> (<code>{redefines atpTarget}</code>): Das endgültig referenzierte Ziel-Datenelement (Blattknoten der Referenz).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Nicht zutreffend (rein statisches Metamodell):</strong> Das Diagramm definiert kein Laufzeitverhalten, sondern das deklarative XML-/ARXML-Schema zur Referenzauflösung.\n</li><li><strong>Pfadauflösungs-Sequenz (Modell-Parser / Tooling):</strong>\n<ol class=\"fig-list\"><li>Identifikation des Root-Containers (<code>base: SwComponentType</code>).\n</li><li>Iterative Traversierung des geordneten Arrays <code>contextComponent</code> zur Lokalisierung der Zielkomponente in der Instanzhierarchie.\n</li><li>Auflösung des Schnittstellen-Ports über <code>contextPortPrototype</code>.\n</li><li>Bestimmung des Wurzel-Datenelements via <code>rootVariableDataPrototype</code> (falls Composite) oder direkter Verweis auf das Ziel via <code>targetDataProtoype</code>.\n</li><li>Sukzessive Dereferenzierung entlang <code>contextDataPrototype</code> zur Bestimmung des spezifischen Feldes bei Composite-Typen.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ARXML-Serialisierung &amp; Toolchain:</strong>\n<ul class=\"fig-list\"><li>Werkzeuge (z. B. DaVinci, EB tresos, Timing Architects) nutzen diese Struktur zur Erzeugung des XML-Tags <code>&lt;VARIABLE-IN-COMPONENT-INSTANCE-REF&gt;</code>.\n</li><li>Das Weglassen von Zwischenknoten in <code>contextComponent</code> oder <code>contextDataPrototype</code> führt zu Schema-Validierungsfehlern (<code>SUBSET_CONTEXT</code>-Verletzung).\n</li></ul>\n</li><li><strong>BSW- / RTE-Konsequenzen:</strong>\n<ul class=\"fig-list\"><li>Für RTE- und MCAL-Entwickler bestimmt dieser Pfad, welche RTE-Puffer, Shared-Memory-Bereiche oder Task-lokale Symbole (<code>Rte_Read_&lt;p&gt;_&lt;o&gt;</code>, <code>Rte_Write_&lt;p&gt;_&lt;o&gt;</code>) mit Timing-Events überwacht werden.\n</li></ul>\n</li><li><strong>Flache vs. hierarchische Ports:</strong>\n<ul class=\"fig-list\"><li>Ist die Variable direkt ein atomares <code>VariableDataPrototype</code> am Port, entfallen <code>rootVariableDataPrototype</code> und <code>contextDataPrototype</code>; <code>targetDataProtoype</code> referenziert direkt das <code>VariableDataPrototype</code>.\n</li></ul>\n</li><li><strong>Ordering-Vorschrift:</strong>\n<ul class=\"fig-list\"><li><code>{ordered}</code> bei <code>contextComponent</code> und <code>contextDataPrototype</code> erzwingt eine strikte Top-Down-Reihenfolge in der ARXML-Datei; Vertauschungen korrumpieren die Referenz.\n</li></ul>\n</li></ul>"}, {"id": "FIG-f7c0e54617d52293", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (AUTOSAR Meta-Modell-Ausschnitt, Structural Pattern).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Timing Extensions (<code>TPS_TimingExtensions</code>, R4.3.1), Kapitel Event- und Timing-Modellierung.\n</li><li><strong>Technischer Zweck:</strong> Eindeutige Adressierung und Instanziierung von Variablen-Datenstrukturen (<code>VariableDataPrototype</code> bzw. Unterelemente von Composite-Datentypen) über SW-C-Hierarchieebenen hinweg. Durch das <code>AtpInstanceRef</code>-Muster wird eineindeutig vom System-/Kompositionstyp über geschachtelte Komponenten- und Port-Prototypen bis zum spezifischen Datenelement navigiert, um Timing-Events, Constraints oder Beobachtungspunkte präzise an ein Laufzeit-Datum zu binden.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metaklassen und Stereotypen</h5>\n<ul class=\"fig-list\"><li><strong><code>AutosarVariableInstance</code></strong> (<code>«Identifiable»</code>): Repräsentiert die konkrete, benannte Instanz einer Variable im Systemkontext für Timing-Analysen. Enthält via optionaler Komposition (<code>+variableInstance 0..1</code>) die Instanzreferenz.\n</li><li><strong><code>VariableInComponentInstanceRef</code></strong> (<code>«AtpInstanceRef»</code>): Kernklasse zur Realisierung des standardisierten AUTOSAR-InstanceRef-Mechanismus für Variablen (ohne Package-Präfix dargestellt).\n</li><li><strong><code>SwComponentType</code></strong> (<code>«ARElement»</code>, <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code>, <code>«AtpType»</code>): Wurzel der Dekomposition (z. B. Composition-Type).\n</li><li><strong><code>SwComponentPrototype</code></strong> (<code>«AtpPrototype»</code>): Repräsentiert die Verwendung eines Komponenten-Typs innerhalb einer Komposition (im Layout oberhalb der Instanzreferenz angeordnet).\n</li><li><strong><code>PortPrototype</code></strong> (<code>«AtpBlueprintable»</code>, <code>«AtpPrototype»</code>): Kommunikations-Port am Komponenten-Typ.\n</li><li><strong><code>DataPrototype</code></strong> (<code>«AtpPrototype»</code>): Abstrakte Basisklasse aller Datenprototypen.\n<ul class=\"fig-list\"><li><strong><code>AutosarDataPrototype</code></strong>: Spezialisierung für AUTOSAR-Datenelemente.\n<ul class=\"fig-list\"><li><strong><code>VariableDataPrototype</code></strong>: Konkretes atomares oder zusammengesetztes Variablenelement an einem Port.\n</li></ul>\n</li><li><strong><code>ApplicationCompositeElementDataPrototype</code></strong>: Sub-Element innerhalb eines strukturierten Datentyps (Record-/Array-Element).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Assoziationen, Kardinalitäten &amp; Semantik</h5>\n<ul class=\"fig-list\"><li><strong><code>AutosarVariableInstance</code> → <code>VariableInComponentInstanceRef</code>:</strong> Komposition <code>+variableInstance 0..1</code> (Instanzreferenz optionalisiert).\n</li><li><strong><code>+base: SwComponentType</code> [1]</strong> (<code>«atpDerived»</code>, <code>{redefines atpBase}</code>): Definiert den Wurzelkontext der Instanziierung.\n</li><li>**<code>+contextComponent: SwComponentPrototype</code> [0..*]** (<code>{ordered, subsets atpContextElement}</code>): Geordnete Pfadliste geschachtelter Subkomponenten von der Wurzel bis zur Zielkomponente.\n</li><li><strong><code>SwComponentPrototype</code> → <code>SwComponentType</code>:</strong> <code>+type 0..1 {redefines atpType}</code> mit Stereotyp <code>«isOfType»</code>.\n</li><li><strong><code>SwComponentType</code> → <code>PortPrototype</code>:</strong> Komposition <code>+port 0..*</code> mit Stereotyp <code>«atpVariation,atpSplitable»</code> (Aggregierte Ports des Komponenten-Typs; unterstützt Variantenbildung und ARXML-Splitting).\n</li><li><strong><code>+contextPortPrototype: PortPrototype</code> [1]</strong> (<code>{subsets atpContextElement}</code>): Eindeutiger Port an der adressierten Blatt-Komponente.\n</li><li><strong><code>+rootVariableDataPrototype: VariableDataPrototype</code> [0..1]</strong> (<code>{subsets atpContextElement}</code>): Wurzelelement der Schnittstelle bei Zugriff auf zusammengesetzte Strukturen.\n</li><li>**<code>+contextDataPrototype: ApplicationCompositeElementDataPrototype</code> [0..*]** (<code>{ordered, subsets atpContextElement}</code>): Geordnete Kette von Composite-Elementen zur Indizierung in geschachtelte Records/Arrays.\n</li><li><strong><code>+targetDataProtoype: DataPrototype</code> [1]</strong> (<code>{redefines atpTarget}</code>): Das endgültig referenzierte Ziel-Datenelement (Blattknoten der Referenz).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Nicht zutreffend (rein statisches Metamodell):</strong> Das Diagramm definiert kein Laufzeitverhalten, sondern das deklarative XML-/ARXML-Schema zur Referenzauflösung.\n</li><li><strong>Pfadauflösungs-Sequenz (Modell-Parser / Tooling):</strong>\n<ol class=\"fig-list\"><li>Identifikation des Root-Containers (<code>base: SwComponentType</code>).\n</li><li>Iterative Traversierung des geordneten Arrays <code>contextComponent</code> zur Lokalisierung der Zielkomponente in der Instanzhierarchie.\n</li><li>Auflösung des Schnittstellen-Ports über <code>contextPortPrototype</code>.\n</li><li>Bestimmung des Wurzel-Datenelements via <code>rootVariableDataPrototype</code> (falls Composite) oder direkter Verweis auf das Ziel via <code>targetDataProtoype</code>.\n</li><li>Sukzessive Dereferenzierung entlang <code>contextDataPrototype</code> zur Bestimmung des spezifischen Feldes bei Composite-Typen.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ARXML-Serialisierung &amp; Toolchain:</strong>\n<ul class=\"fig-list\"><li>Werkzeuge (z. B. DaVinci, EB tresos, Timing Architects) nutzen diese Struktur zur Erzeugung des XML-Tags <code>&lt;VARIABLE-IN-COMPONENT-INSTANCE-REF&gt;</code>.\n</li><li>Das Weglassen von Zwischenknoten in <code>contextComponent</code> oder <code>contextDataPrototype</code> führt zu Schema-Validierungsfehlern (<code>SUBSET_CONTEXT</code>-Verletzung).\n</li></ul>\n</li><li><strong>BSW- / RTE-Konsequenzen:</strong>\n<ul class=\"fig-list\"><li>Für RTE- und MCAL-Entwickler bestimmt dieser Pfad, welche RTE-Puffer, Shared-Memory-Bereiche oder Task-lokale Symbole (<code>Rte_Read_&lt;p&gt;_&lt;o&gt;</code>, <code>Rte_Write_&lt;p&gt;_&lt;o&gt;</code>) mit Timing-Events überwacht werden.\n</li></ul>\n</li><li><strong>Flache vs. hierarchische Ports:</strong>\n<ul class=\"fig-list\"><li>Ist die Variable direkt ein atomares <code>VariableDataPrototype</code> am Port, entfallen <code>rootVariableDataPrototype</code> und <code>contextDataPrototype</code>; <code>targetDataProtoype</code> referenziert direkt das <code>VariableDataPrototype</code>.\n</li></ul>\n</li><li><strong>Ordering-Vorschrift:</strong>\n<ul class=\"fig-list\"><li><code>{ordered}</code> bei <code>contextComponent</code> und <code>contextDataPrototype</code> erzwingt eine strikte Top-Down-Reihenfolge in der ARXML-Datei; Vertauschungen korrumpieren die Referenz.\n</li></ul>\n</li></ul>"}, {"id": "FIG-39871e530b862441", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm des AUTOSAR-Metamodells (M2) aus der Spezifikation <em>AUTOSAR_TPS_TimingExtensions</em> (Kapitel <em>Referencing Variable Instances</em>). Das Diagramm spezifiziert die Metaklassen und Assoziationen zur eindeutigen Adressierung und Kontextualisierung einer Variableninstanz (<code>AutosarVariableInstance</code>) über hierarchische Software-Architekturen hinweg mittels des generischen AUTOSAR-Instanzreferenzmusters (<code>AtpInstanceRef</code>). Es verbindet die funktionale Komponentenarchitektur (Kompositionen, Prototypen, Ports) mit typisierten Datenstrukturen und Signalpfaden zur präzisen zeitlichen Modellierung von Variablenzugriffen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Element ist die Metaklasse <code>VariableInComponentInstanceRef</code> (Spezialisierung von <code>AtpInstanceRef</code>), die über eine Komposition (<code>+variableInstance</code>, Kardinalität <code>0..1</code>) von <code>AutosarVariableInstance</code> (abgeleitet von <code>Identifiable</code>) referenziert wird. <code>VariableInComponentInstanceRef</code> definiert folgende Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>+base</code>: Multiplizität <code>1</code>, redefiniert <code>atpBase</code>, mit Stereotyp <code>«atpDerived»</code>, referenziert <code>SwComponentType</code>.\n</li><li><code>+contextComponent</code>: Multiplizität <code>0..*</code>, geordnet (<code>{ordered}</code>), subsetzt <code>atpContextElement</code>, referenziert <code>SwComponentPrototype</code> (Stereotyp <code>«atpPrototype»</code>).\n</li><li><code>+contextPortPrototype</code>: Multiplizität <code>1</code>, subsetzt <code>atpContextElement</code>, referenziert <code>PortPrototype</code> (Stereotypen <code>«atpBlueprintable»</code>, <code>«atpPrototype»</code>).\n</li><li><code>+rootVariableDataPrototype</code>: Multiplizität <code>0..1</code>, subsetzt <code>atpContextElement</code>, referenziert <code>VariableDataPrototype</code>.\n</li><li><code>+contextDataPrototype</code>: Multiplizität <code>0..*</code>, geordnet (<code>{ordered}</code>), subsetzt <code>atpContextElement</code>, referenziert <code>ApplicationCompositeElementDataPrototype</code>.\n</li><li><code>+targetDataProtoype</code>: Multiplizität <code>1</code>, redefiniert <code>atpTarget</code>, referenziert <code>DataPrototype</code> (Stereotyp <code>«atpPrototype»</code>).\n</li></ul>\n<p class=\"fig-p\">Zusätzliche Metaklassen und Vererbungsbeziehungen:</p>\n<ul class=\"fig-list\"><li><code>SwComponentType</code> (Stereotypen <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>) besitzt über <code>+port</code> (<code>0..*</code>, Stereotypen <code>«atpVariation, atpSplitable»</code>) aggregierte <code>PortPrototype</code>-Elemente.\n</li><li><code>SwComponentPrototype</code> referenziert über <code>+type</code> (<code>0..1</code>, redefiniert <code>atpType</code>, Stereotyp <code>«isOfType»</code>) den zugehörigen <code>SwComponentType</code>.\n</li><li><code>DataPrototype</code> bildet die abstrakte Basis für <code>AutosarDataPrototype</code> und <code>ApplicationCompositeElementDataPrototype</code>.\n</li><li><code>VariableDataPrototype</code> spezialisiert <code>AutosarDataPrototype</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Klassendiagramm beschreibt die Abbildung keine dynamischen Ausführungssequenzen oder Laufzeitinteraktionen. Dynamisch relevant ist der deterministische Auflösungsalgorithmus des Instanzpfads zur Konfigurations- bzw. Analysezeit:</p>\n<ol class=\"fig-list\"><li>Identifikation der System- bzw. Kompositionsebene über <code>base</code> (<code>SwComponentType</code>).\n</li><li>Abstieg durch die Komponenten-Hierarchie entlang der geordneten Sequenz <code>contextComponent</code> (<code>SwComponentPrototype</code>).\n</li><li>Lokalisierung des Schnittstellen-Ports über <code>contextPortPrototype</code> (<code>PortPrototype</code>).\n</li><li>Auflösung des Wurzel-Datenelements der Port-Schnittstelle über <code>rootVariableDataPrototype</code> (<code>VariableDataPrototype</code>).\n</li><li>Bei zusammengesetzten Datentypen strukturierter Abstieg durch die Datenelementhierarchie über die geordnete Kette <code>contextDataPrototype</code> (<code>ApplicationCompositeElementDataPrototype</code>).\n</li><li>Finale Auflösung und Bindung des Ziel-Datenelements am Blatt des Pfades über <code>targetDataProtoype</code> (<code>DataPrototype</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindlich für die Modellierung von Timing-Ereignissen und Datenflussanalysen in AUTOSAR Classic und Adaptive Platform. Werkzeugketten (Authoring Tools, Timing-Analysatoren) müssen folgende Integritätsregeln durchsetzen:</p>\n<ul class=\"fig-list\"><li>Exakte Einhaltung des XML-Schemabezeichners <code>targetDataProtoype</code> (mit dem normativen Schreibfehler ohne zweites „t“ in „Protoype“).\n</li><li>Die Attribute <code>contextComponent</code> und <code>contextDataPrototype</code> müssen in ARXML streng die durch <code>{ordered}</code> vorgegebene Top-Down-Reihenfolge einhalten; Verletzungen führen zu ungültigen Instanzauflösungen.\n</li><li>Die Kardinalitäten <code>contextPortPrototype</code> (exakt <code>1</code>) und <code>targetDataProtoype</code> (exakt <code>1</code>) sind obligatorisch.\n</li><li>Das Attribut <code>base</code> ist als <code>«atpDerived»</code> markiert und muss von Modellierungswerkzeugen konsistent aus dem übergeordneten Architekturkontext abgeleitet werden.\n</li><li>Variabilitäts- und Splitmechanismen (<code>«atpVariation, atpSplitable»</code> an <code>+port</code>) erfordern, dass Instanzreferenzen auch bei variantenabhängigen Systemkonfigurationen eindeutig auflösbar bleiben.\n</li></ul>"}, {"id": "FIG-49c974f1395a45ae", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm des AUTOSAR-Metamodells (M2) aus der Spezifikation <em>AUTOSAR_TPS_TimingExtensions</em> (Kapitel <em>Referencing Variable Instances</em>). Das Diagramm spezifiziert die Metaklassen und Assoziationen zur eindeutigen Adressierung und Kontextualisierung einer Variableninstanz (<code>AutosarVariableInstance</code>) über hierarchische Software-Architekturen hinweg mittels des generischen AUTOSAR-Instanzreferenzmusters (<code>AtpInstanceRef</code>). Es verbindet die funktionale Komponentenarchitektur (Kompositionen, Prototypen, Ports) mit typisierten Datenstrukturen und Signalpfaden zur präzisen zeitlichen Modellierung von Variablenzugriffen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Element ist die Metaklasse <code>VariableInComponentInstanceRef</code> (Spezialisierung von <code>AtpInstanceRef</code>), die über eine Komposition (<code>+variableInstance</code>, Kardinalität <code>0..1</code>) von <code>AutosarVariableInstance</code> (abgeleitet von <code>Identifiable</code>) referenziert wird. <code>VariableInComponentInstanceRef</code> definiert folgende Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>+base</code>: Multiplizität <code>1</code>, redefiniert <code>atpBase</code>, mit Stereotyp <code>«atpDerived»</code>, referenziert <code>SwComponentType</code>.\n</li><li><code>+contextComponent</code>: Multiplizität <code>0..*</code>, geordnet (<code>{ordered}</code>), subsetzt <code>atpContextElement</code>, referenziert <code>SwComponentPrototype</code> (Stereotyp <code>«atpPrototype»</code>).\n</li><li><code>+contextPortPrototype</code>: Multiplizität <code>1</code>, subsetzt <code>atpContextElement</code>, referenziert <code>PortPrototype</code> (Stereotypen <code>«atpBlueprintable»</code>, <code>«atpPrototype»</code>).\n</li><li><code>+rootVariableDataPrototype</code>: Multiplizität <code>0..1</code>, subsetzt <code>atpContextElement</code>, referenziert <code>VariableDataPrototype</code>.\n</li><li><code>+contextDataPrototype</code>: Multiplizität <code>0..*</code>, geordnet (<code>{ordered}</code>), subsetzt <code>atpContextElement</code>, referenziert <code>ApplicationCompositeElementDataPrototype</code>.\n</li><li><code>+targetDataProtoype</code>: Multiplizität <code>1</code>, redefiniert <code>atpTarget</code>, referenziert <code>DataPrototype</code> (Stereotyp <code>«atpPrototype»</code>).\n</li></ul>\n<p class=\"fig-p\">Zusätzliche Metaklassen und Vererbungsbeziehungen:</p>\n<ul class=\"fig-list\"><li><code>SwComponentType</code> (Stereotypen <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>) besitzt über <code>+port</code> (<code>0..*</code>, Stereotypen <code>«atpVariation, atpSplitable»</code>) aggregierte <code>PortPrototype</code>-Elemente.\n</li><li><code>SwComponentPrototype</code> referenziert über <code>+type</code> (<code>0..1</code>, redefiniert <code>atpType</code>, Stereotyp <code>«isOfType»</code>) den zugehörigen <code>SwComponentType</code>.\n</li><li><code>DataPrototype</code> bildet die abstrakte Basis für <code>AutosarDataPrototype</code> und <code>ApplicationCompositeElementDataPrototype</code>.\n</li><li><code>VariableDataPrototype</code> spezialisiert <code>AutosarDataPrototype</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Klassendiagramm beschreibt die Abbildung keine dynamischen Ausführungssequenzen oder Laufzeitinteraktionen. Dynamisch relevant ist der deterministische Auflösungsalgorithmus des Instanzpfads zur Konfigurations- bzw. Analysezeit:</p>\n<ol class=\"fig-list\"><li>Identifikation der System- bzw. Kompositionsebene über <code>base</code> (<code>SwComponentType</code>).\n</li><li>Abstieg durch die Komponenten-Hierarchie entlang der geordneten Sequenz <code>contextComponent</code> (<code>SwComponentPrototype</code>).\n</li><li>Lokalisierung des Schnittstellen-Ports über <code>contextPortPrototype</code> (<code>PortPrototype</code>).\n</li><li>Auflösung des Wurzel-Datenelements der Port-Schnittstelle über <code>rootVariableDataPrototype</code> (<code>VariableDataPrototype</code>).\n</li><li>Bei zusammengesetzten Datentypen strukturierter Abstieg durch die Datenelementhierarchie über die geordnete Kette <code>contextDataPrototype</code> (<code>ApplicationCompositeElementDataPrototype</code>).\n</li><li>Finale Auflösung und Bindung des Ziel-Datenelements am Blatt des Pfades über <code>targetDataProtoype</code> (<code>DataPrototype</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindlich für die Modellierung von Timing-Ereignissen und Datenflussanalysen in AUTOSAR Classic und Adaptive Platform. Werkzeugketten (Authoring Tools, Timing-Analysatoren) müssen folgende Integritätsregeln durchsetzen:</p>\n<ul class=\"fig-list\"><li>Exakte Einhaltung des XML-Schemabezeichners <code>targetDataProtoype</code> (mit dem normativen Schreibfehler ohne zweites „t“ in „Protoype“).\n</li><li>Die Attribute <code>contextComponent</code> und <code>contextDataPrototype</code> müssen in ARXML streng die durch <code>{ordered}</code> vorgegebene Top-Down-Reihenfolge einhalten; Verletzungen führen zu ungültigen Instanzauflösungen.\n</li><li>Die Kardinalitäten <code>contextPortPrototype</code> (exakt <code>1</code>) und <code>targetDataProtoype</code> (exakt <code>1</code>) sind obligatorisch.\n</li><li>Das Attribut <code>base</code> ist als <code>«atpDerived»</code> markiert und muss von Modellierungswerkzeugen konsistent aus dem übergeordneten Architekturkontext abgeleitet werden.\n</li><li>Variabilitäts- und Splitmechanismen (<code>«atpVariation, atpSplitable»</code> an <code>+port</code>) erfordern, dass Instanzreferenzen auch bei variantenabhängigen Systemkonfigurationen eindeutig auflösbar bleiben.\n</li></ul>"}, {"id": "FIG-deae36305ff3384f", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (AUTOSAR Meta-Modell-Ausschnitt, Structural Pattern).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Timing Extensions (<code>TPS_TimingExtensions</code>, R4.3.1), Kapitel Event- und Timing-Modellierung.\n</li><li><strong>Technischer Zweck:</strong> Eindeutige Adressierung und Instanziierung von Variablen-Datenstrukturen (<code>VariableDataPrototype</code> bzw. Unterelemente von Composite-Datentypen) über SW-C-Hierarchieebenen hinweg. Durch das <code>AtpInstanceRef</code>-Muster wird eineindeutig vom System-/Kompositionstyp über geschachtelte Komponenten- und Port-Prototypen bis zum spezifischen Datenelement navigiert, um Timing-Events, Constraints oder Beobachtungspunkte präzise an ein Laufzeit-Datum zu binden.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metaklassen und Stereotypen</h5>\n<ul class=\"fig-list\"><li><strong><code>AutosarVariableInstance</code></strong> (<code>«Identifiable»</code>): Repräsentiert die konkrete, benannte Instanz einer Variable im Systemkontext für Timing-Analysen. Enthält via optionaler Komposition (<code>+variableInstance 0..1</code>) die Instanzreferenz.\n</li><li><strong><code>VariableInComponentInstanceRef</code></strong> (<code>«AtpInstanceRef»</code>): Kernklasse zur Realisierung des standardisierten AUTOSAR-InstanceRef-Mechanismus für Variablen (ohne Package-Präfix dargestellt).\n</li><li><strong><code>SwComponentType</code></strong> (<code>«ARElement»</code>, <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code>, <code>«AtpType»</code>): Wurzel der Dekomposition (z. B. Composition-Type).\n</li><li><strong><code>SwComponentPrototype</code></strong> (<code>«AtpPrototype»</code>): Repräsentiert die Verwendung eines Komponenten-Typs innerhalb einer Komposition (im Layout oberhalb der Instanzreferenz angeordnet).\n</li><li><strong><code>PortPrototype</code></strong> (<code>«AtpBlueprintable»</code>, <code>«AtpPrototype»</code>): Kommunikations-Port am Komponenten-Typ.\n</li><li><strong><code>DataPrototype</code></strong> (<code>«AtpPrototype»</code>): Abstrakte Basisklasse aller Datenprototypen.\n<ul class=\"fig-list\"><li><strong><code>AutosarDataPrototype</code></strong>: Spezialisierung für AUTOSAR-Datenelemente.\n<ul class=\"fig-list\"><li><strong><code>VariableDataPrototype</code></strong>: Konkretes atomares oder zusammengesetztes Variablenelement an einem Port.\n</li></ul>\n</li><li><strong><code>ApplicationCompositeElementDataPrototype</code></strong>: Sub-Element innerhalb eines strukturierten Datentyps (Record-/Array-Element).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Assoziationen, Kardinalitäten &amp; Semantik</h5>\n<ul class=\"fig-list\"><li><strong><code>AutosarVariableInstance</code> → <code>VariableInComponentInstanceRef</code>:</strong> Komposition <code>+variableInstance 0..1</code> (Instanzreferenz optionalisiert).\n</li><li><strong><code>+base: SwComponentType</code> [1]</strong> (<code>«atpDerived»</code>, <code>{redefines atpBase}</code>): Definiert den Wurzelkontext der Instanziierung.\n</li><li>**<code>+contextComponent: SwComponentPrototype</code> [0..*]** (<code>{ordered, subsets atpContextElement}</code>): Geordnete Pfadliste geschachtelter Subkomponenten von der Wurzel bis zur Zielkomponente.\n</li><li><strong><code>SwComponentPrototype</code> → <code>SwComponentType</code>:</strong> <code>+type 0..1 {redefines atpType}</code> mit Stereotyp <code>«isOfType»</code>.\n</li><li><strong><code>SwComponentType</code> → <code>PortPrototype</code>:</strong> Komposition <code>+port 0..*</code> mit Stereotyp <code>«atpVariation,atpSplitable»</code> (Aggregierte Ports des Komponenten-Typs; unterstützt Variantenbildung und ARXML-Splitting).\n</li><li><strong><code>+contextPortPrototype: PortPrototype</code> [1]</strong> (<code>{subsets atpContextElement}</code>): Eindeutiger Port an der adressierten Blatt-Komponente.\n</li><li><strong><code>+rootVariableDataPrototype: VariableDataPrototype</code> [0..1]</strong> (<code>{subsets atpContextElement}</code>): Wurzelelement der Schnittstelle bei Zugriff auf zusammengesetzte Strukturen.\n</li><li>**<code>+contextDataPrototype: ApplicationCompositeElementDataPrototype</code> [0..*]** (<code>{ordered, subsets atpContextElement}</code>): Geordnete Kette von Composite-Elementen zur Indizierung in geschachtelte Records/Arrays.\n</li><li><strong><code>+targetDataProtoype: DataPrototype</code> [1]</strong> (<code>{redefines atpTarget}</code>): Das endgültig referenzierte Ziel-Datenelement (Blattknoten der Referenz).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Nicht zutreffend (rein statisches Metamodell):</strong> Das Diagramm definiert kein Laufzeitverhalten, sondern das deklarative XML-/ARXML-Schema zur Referenzauflösung.\n</li><li><strong>Pfadauflösungs-Sequenz (Modell-Parser / Tooling):</strong>\n<ol class=\"fig-list\"><li>Identifikation des Root-Containers (<code>base: SwComponentType</code>).\n</li><li>Iterative Traversierung des geordneten Arrays <code>contextComponent</code> zur Lokalisierung der Zielkomponente in der Instanzhierarchie.\n</li><li>Auflösung des Schnittstellen-Ports über <code>contextPortPrototype</code>.\n</li><li>Bestimmung des Wurzel-Datenelements via <code>rootVariableDataPrototype</code> (falls Composite) oder direkter Verweis auf das Ziel via <code>targetDataProtoype</code>.\n</li><li>Sukzessive Dereferenzierung entlang <code>contextDataPrototype</code> zur Bestimmung des spezifischen Feldes bei Composite-Typen.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ARXML-Serialisierung &amp; Toolchain:</strong>\n<ul class=\"fig-list\"><li>Werkzeuge (z. B. DaVinci, EB tresos, Timing Architects) nutzen diese Struktur zur Erzeugung des XML-Tags <code>&lt;VARIABLE-IN-COMPONENT-INSTANCE-REF&gt;</code>.\n</li><li>Das Weglassen von Zwischenknoten in <code>contextComponent</code> oder <code>contextDataPrototype</code> führt zu Schema-Validierungsfehlern (<code>SUBSET_CONTEXT</code>-Verletzung).\n</li></ul>\n</li><li><strong>BSW- / RTE-Konsequenzen:</strong>\n<ul class=\"fig-list\"><li>Für RTE- und MCAL-Entwickler bestimmt dieser Pfad, welche RTE-Puffer, Shared-Memory-Bereiche oder Task-lokale Symbole (<code>Rte_Read_&lt;p&gt;_&lt;o&gt;</code>, <code>Rte_Write_&lt;p&gt;_&lt;o&gt;</code>) mit Timing-Events überwacht werden.\n</li></ul>\n</li><li><strong>Flache vs. hierarchische Ports:</strong>\n<ul class=\"fig-list\"><li>Ist die Variable direkt ein atomares <code>VariableDataPrototype</code> am Port, entfallen <code>rootVariableDataPrototype</code> und <code>contextDataPrototype</code>; <code>targetDataProtoype</code> referenziert direkt das <code>VariableDataPrototype</code>.\n</li></ul>\n</li><li><strong>Ordering-Vorschrift:</strong>\n<ul class=\"fig-list\"><li><code>{ordered}</code> bei <code>contextComponent</code> und <code>contextDataPrototype</code> erzwingt eine strikte Top-Down-Reihenfolge in der ARXML-Datei; Vertauschungen korrumpieren die Referenz.\n</li></ul>\n</li></ul>"}, {"id": "FIG-1ba482283a1c1421", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm des AUTOSAR-Metamodells (M2) aus der Spezifikation <em>AUTOSAR_TPS_TimingExtensions</em> (Kapitel <em>Referencing Variable Instances</em>). Das Diagramm spezifiziert die Metaklassen und Assoziationen zur eindeutigen Adressierung und Kontextualisierung einer Variableninstanz (<code>AutosarVariableInstance</code>) über hierarchische Software-Architekturen hinweg mittels des generischen AUTOSAR-Instanzreferenzmusters (<code>AtpInstanceRef</code>). Es verbindet die funktionale Komponentenarchitektur (Kompositionen, Prototypen, Ports) mit typisierten Datenstrukturen und Signalpfaden zur präzisen zeitlichen Modellierung von Variablenzugriffen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Element ist die Metaklasse <code>VariableInComponentInstanceRef</code> (Spezialisierung von <code>AtpInstanceRef</code>), die über eine Komposition (<code>+variableInstance</code>, Kardinalität <code>0..1</code>) von <code>AutosarVariableInstance</code> (abgeleitet von <code>Identifiable</code>) referenziert wird. <code>VariableInComponentInstanceRef</code> definiert folgende Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>+base</code>: Multiplizität <code>1</code>, redefiniert <code>atpBase</code>, mit Stereotyp <code>«atpDerived»</code>, referenziert <code>SwComponentType</code>.\n</li><li><code>+contextComponent</code>: Multiplizität <code>0..*</code>, geordnet (<code>{ordered}</code>), subsetzt <code>atpContextElement</code>, referenziert <code>SwComponentPrototype</code> (Stereotyp <code>«atpPrototype»</code>).\n</li><li><code>+contextPortPrototype</code>: Multiplizität <code>1</code>, subsetzt <code>atpContextElement</code>, referenziert <code>PortPrototype</code> (Stereotypen <code>«atpBlueprintable»</code>, <code>«atpPrototype»</code>).\n</li><li><code>+rootVariableDataPrototype</code>: Multiplizität <code>0..1</code>, subsetzt <code>atpContextElement</code>, referenziert <code>VariableDataPrototype</code>.\n</li><li><code>+contextDataPrototype</code>: Multiplizität <code>0..*</code>, geordnet (<code>{ordered}</code>), subsetzt <code>atpContextElement</code>, referenziert <code>ApplicationCompositeElementDataPrototype</code>.\n</li><li><code>+targetDataProtoype</code>: Multiplizität <code>1</code>, redefiniert <code>atpTarget</code>, referenziert <code>DataPrototype</code> (Stereotyp <code>«atpPrototype»</code>).\n</li></ul>\n<p class=\"fig-p\">Zusätzliche Metaklassen und Vererbungsbeziehungen:</p>\n<ul class=\"fig-list\"><li><code>SwComponentType</code> (Stereotypen <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>) besitzt über <code>+port</code> (<code>0..*</code>, Stereotypen <code>«atpVariation, atpSplitable»</code>) aggregierte <code>PortPrototype</code>-Elemente.\n</li><li><code>SwComponentPrototype</code> referenziert über <code>+type</code> (<code>0..1</code>, redefiniert <code>atpType</code>, Stereotyp <code>«isOfType»</code>) den zugehörigen <code>SwComponentType</code>.\n</li><li><code>DataPrototype</code> bildet die abstrakte Basis für <code>AutosarDataPrototype</code> und <code>ApplicationCompositeElementDataPrototype</code>.\n</li><li><code>VariableDataPrototype</code> spezialisiert <code>AutosarDataPrototype</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Klassendiagramm beschreibt die Abbildung keine dynamischen Ausführungssequenzen oder Laufzeitinteraktionen. Dynamisch relevant ist der deterministische Auflösungsalgorithmus des Instanzpfads zur Konfigurations- bzw. Analysezeit:</p>\n<ol class=\"fig-list\"><li>Identifikation der System- bzw. Kompositionsebene über <code>base</code> (<code>SwComponentType</code>).\n</li><li>Abstieg durch die Komponenten-Hierarchie entlang der geordneten Sequenz <code>contextComponent</code> (<code>SwComponentPrototype</code>).\n</li><li>Lokalisierung des Schnittstellen-Ports über <code>contextPortPrototype</code> (<code>PortPrototype</code>).\n</li><li>Auflösung des Wurzel-Datenelements der Port-Schnittstelle über <code>rootVariableDataPrototype</code> (<code>VariableDataPrototype</code>).\n</li><li>Bei zusammengesetzten Datentypen strukturierter Abstieg durch die Datenelementhierarchie über die geordnete Kette <code>contextDataPrototype</code> (<code>ApplicationCompositeElementDataPrototype</code>).\n</li><li>Finale Auflösung und Bindung des Ziel-Datenelements am Blatt des Pfades über <code>targetDataProtoype</code> (<code>DataPrototype</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindlich für die Modellierung von Timing-Ereignissen und Datenflussanalysen in AUTOSAR Classic und Adaptive Platform. Werkzeugketten (Authoring Tools, Timing-Analysatoren) müssen folgende Integritätsregeln durchsetzen:</p>\n<ul class=\"fig-list\"><li>Exakte Einhaltung des XML-Schemabezeichners <code>targetDataProtoype</code> (mit dem normativen Schreibfehler ohne zweites „t“ in „Protoype“).\n</li><li>Die Attribute <code>contextComponent</code> und <code>contextDataPrototype</code> müssen in ARXML streng die durch <code>{ordered}</code> vorgegebene Top-Down-Reihenfolge einhalten; Verletzungen führen zu ungültigen Instanzauflösungen.\n</li><li>Die Kardinalitäten <code>contextPortPrototype</code> (exakt <code>1</code>) und <code>targetDataProtoype</code> (exakt <code>1</code>) sind obligatorisch.\n</li><li>Das Attribut <code>base</code> ist als <code>«atpDerived»</code> markiert und muss von Modellierungswerkzeugen konsistent aus dem übergeordneten Architekturkontext abgeleitet werden.\n</li><li>Variabilitäts- und Splitmechanismen (<code>«atpVariation, atpSplitable»</code> an <code>+port</code>) erfordern, dass Instanzreferenzen auch bei variantenabhängigen Systemkonfigurationen eindeutig auflösbar bleiben.\n</li></ul>"}, {"id": "FIG-148ffb93918bdaa5", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm des AUTOSAR-Metamodells (M2) aus der Spezifikation <em>AUTOSAR_TPS_TimingExtensions</em> (Kapitel <em>Referencing Variable Instances</em>). Das Diagramm spezifiziert die Metaklassen und Assoziationen zur eindeutigen Adressierung und Kontextualisierung einer Variableninstanz (<code>AutosarVariableInstance</code>) über hierarchische Software-Architekturen hinweg mittels des generischen AUTOSAR-Instanzreferenzmusters (<code>AtpInstanceRef</code>). Es verbindet die funktionale Komponentenarchitektur (Kompositionen, Prototypen, Ports) mit typisierten Datenstrukturen und Signalpfaden zur präzisen zeitlichen Modellierung von Variablenzugriffen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Element ist die Metaklasse <code>VariableInComponentInstanceRef</code> (Spezialisierung von <code>AtpInstanceRef</code>), die über eine Komposition (<code>+variableInstance</code>, Kardinalität <code>0..1</code>) von <code>AutosarVariableInstance</code> (abgeleitet von <code>Identifiable</code>) referenziert wird. <code>VariableInComponentInstanceRef</code> definiert folgende Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>+base</code>: Multiplizität <code>1</code>, redefiniert <code>atpBase</code>, mit Stereotyp <code>«atpDerived»</code>, referenziert <code>SwComponentType</code>.\n</li><li><code>+contextComponent</code>: Multiplizität <code>0..*</code>, geordnet (<code>{ordered}</code>), subsetzt <code>atpContextElement</code>, referenziert <code>SwComponentPrototype</code> (Stereotyp <code>«atpPrototype»</code>).\n</li><li><code>+contextPortPrototype</code>: Multiplizität <code>1</code>, subsetzt <code>atpContextElement</code>, referenziert <code>PortPrototype</code> (Stereotypen <code>«atpBlueprintable»</code>, <code>«atpPrototype»</code>).\n</li><li><code>+rootVariableDataPrototype</code>: Multiplizität <code>0..1</code>, subsetzt <code>atpContextElement</code>, referenziert <code>VariableDataPrototype</code>.\n</li><li><code>+contextDataPrototype</code>: Multiplizität <code>0..*</code>, geordnet (<code>{ordered}</code>), subsetzt <code>atpContextElement</code>, referenziert <code>ApplicationCompositeElementDataPrototype</code>.\n</li><li><code>+targetDataProtoype</code>: Multiplizität <code>1</code>, redefiniert <code>atpTarget</code>, referenziert <code>DataPrototype</code> (Stereotyp <code>«atpPrototype»</code>).\n</li></ul>\n<p class=\"fig-p\">Zusätzliche Metaklassen und Vererbungsbeziehungen:</p>\n<ul class=\"fig-list\"><li><code>SwComponentType</code> (Stereotypen <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>) besitzt über <code>+port</code> (<code>0..*</code>, Stereotypen <code>«atpVariation, atpSplitable»</code>) aggregierte <code>PortPrototype</code>-Elemente.\n</li><li><code>SwComponentPrototype</code> referenziert über <code>+type</code> (<code>0..1</code>, redefiniert <code>atpType</code>, Stereotyp <code>«isOfType»</code>) den zugehörigen <code>SwComponentType</code>.\n</li><li><code>DataPrototype</code> bildet die abstrakte Basis für <code>AutosarDataPrototype</code> und <code>ApplicationCompositeElementDataPrototype</code>.\n</li><li><code>VariableDataPrototype</code> spezialisiert <code>AutosarDataPrototype</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Klassendiagramm beschreibt die Abbildung keine dynamischen Ausführungssequenzen oder Laufzeitinteraktionen. Dynamisch relevant ist der deterministische Auflösungsalgorithmus des Instanzpfads zur Konfigurations- bzw. Analysezeit:</p>\n<ol class=\"fig-list\"><li>Identifikation der System- bzw. Kompositionsebene über <code>base</code> (<code>SwComponentType</code>).\n</li><li>Abstieg durch die Komponenten-Hierarchie entlang der geordneten Sequenz <code>contextComponent</code> (<code>SwComponentPrototype</code>).\n</li><li>Lokalisierung des Schnittstellen-Ports über <code>contextPortPrototype</code> (<code>PortPrototype</code>).\n</li><li>Auflösung des Wurzel-Datenelements der Port-Schnittstelle über <code>rootVariableDataPrototype</code> (<code>VariableDataPrototype</code>).\n</li><li>Bei zusammengesetzten Datentypen strukturierter Abstieg durch die Datenelementhierarchie über die geordnete Kette <code>contextDataPrototype</code> (<code>ApplicationCompositeElementDataPrototype</code>).\n</li><li>Finale Auflösung und Bindung des Ziel-Datenelements am Blatt des Pfades über <code>targetDataProtoype</code> (<code>DataPrototype</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindlich für die Modellierung von Timing-Ereignissen und Datenflussanalysen in AUTOSAR Classic und Adaptive Platform. Werkzeugketten (Authoring Tools, Timing-Analysatoren) müssen folgende Integritätsregeln durchsetzen:</p>\n<ul class=\"fig-list\"><li>Exakte Einhaltung des XML-Schemabezeichners <code>targetDataProtoype</code> (mit dem normativen Schreibfehler ohne zweites „t“ in „Protoype“).\n</li><li>Die Attribute <code>contextComponent</code> und <code>contextDataPrototype</code> müssen in ARXML streng die durch <code>{ordered}</code> vorgegebene Top-Down-Reihenfolge einhalten; Verletzungen führen zu ungültigen Instanzauflösungen.\n</li><li>Die Kardinalitäten <code>contextPortPrototype</code> (exakt <code>1</code>) und <code>targetDataProtoype</code> (exakt <code>1</code>) sind obligatorisch.\n</li><li>Das Attribut <code>base</code> ist als <code>«atpDerived»</code> markiert und muss von Modellierungswerkzeugen konsistent aus dem übergeordneten Architekturkontext abgeleitet werden.\n</li><li>Variabilitäts- und Splitmechanismen (<code>«atpVariation, atpSplitable»</code> an <code>+port</code>) erfordern, dass Instanzreferenzen auch bei variantenabhängigen Systemkonfigurationen eindeutig auflösbar bleiben.\n</li></ul>"}], "trans": [{"from": "FIG-3b3943d88a27ce49", "to": "FIG-2b7f44590b45d4d7", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-2b7f44590b45d4d7", "to": "FIG-93df5ad9225607cb", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-93df5ad9225607cb", "to": "FIG-5f68178a3c5ee387", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>SwComponentPrototype</code>: Multiplizität der Assoziation <code>+type</code> zu <code>SwComponentType</code> von <code>1</code> auf <code>0..1</code> geändert (<code>+type 0..1 {redefines atpType}</code>).\n</li></ul>"}, {"from": "FIG-5f68178a3c5ee387", "to": "FIG-f7c0e54617d52293", "fr": "R20-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>AutosarVariableInstance</code>: Multiplizität der Komposition <code>+variableInstance</code> zu <code>VariableInComponentInstanceRef</code> von <code>1</code> auf <code>0..1</code> gelockert.\n</li><li><code>SwComponentType</code>: Neue Komposition <code>+port 0..*</code> mit den Stereotypen <code>«atpVariation,atpSplitable»</code> zu <code>PortPrototype</code> ergänzt.\n</li><li>Alle Metaklassen (<code>VariableInComponentInstanceRef</code>, <code>SwComponentPrototype</code>, <code>SwComponentType</code>, <code>PortPrototype</code>, <code>DataPrototype</code> etc.): Metamodell-Package-Präfixe (<code>InstanceRefs::</code>, <code>Composition::</code>, <code>Components::</code>, <code>DataPrototypes::</code>) aus den Klassenbezeichnungen entfernt.\n</li><li><code>SwComponentPrototype</code>: Im Diagrammlayout von rechts oben nach mittig oben oberhalb von <code>VariableInComponentInstanceRef</code> verschoben.\n</li></ul>"}, {"from": "FIG-f7c0e54617d52293", "to": "FIG-deae36305ff3384f", "fr": "R22-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
